package fft

import "github.com/go-fft/fft/internal/kernels"

// fused1024Enabled is whether a fused plan of 1024 points runs the one-kernel
// transform (kernels.Fused1024, generated by internal/genfused256): two 32x32
// passes, the twiddles between them folded into the first, the 32-point DFTs held
// in zmm registers (with spills). A variable for the same reasons as
// fused256Enabled.
var fused1024Enabled = kernels.Fused1024On

// fused1024Route reports whether a fused plan of n points takes the kernel.
// Exact and NoFMA plans never do (their arithmetic is not fused), and nor does
// any CPU but the Zen 4 the kernel was measured on (go-fft/fft#162).
func fused1024Route(n int) bool { return n == 1024 && fused1024Enabled }
